function CountFiltered(strings: seq<string>, prefix: string): int
    reads strings
    requires strings != null
    requires forall i :: 0 <= i < |strings| ==> strings[i] != null
    requires |prefix| > 0
    ensures CountFiltered(strings, prefix) >= 0
    ensures CountFiltered(strings, prefix) == |{ s | s in strings && s.StartsWith(prefix) }|
{
    var count := 0;
    var i := 0;
    while i < |strings|
        invariant 0 <= count <= i
        invariant i <= |strings|
    {
        if strings[i].StartsWith(prefix) {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}
